INSERT INTO `broadcast_text_locale` VALUES (19778,'frFR','La Fédération de Rencontres d’Arène de Gentepression va bientôt lancer son championnat. Il y a déjà des combats d’entraînement dans les arènes, mais les matchs officiels ne commenceront que dans $4262d.','La Fédération de Rencontres d’Arène de Gentepression va bientôt lancer son championnat. Il y a déjà des combats d’entraînement dans les arènes, mais les matchs officiels ne commenceront que dans $4262d.',26124),(19779,'enUS','Destroy them, Torloth. Let loose their blood like a river upon this hallowed ground.','',26124),(19779,'frFR','Détruis-les, Torloth. Que leur sang se répande telle une rivière sur ce sol sacré.','',26124),(19780,'enUS','The goblin Steamwheedle Fighting Circuit has begun. You can find Arena Organizers selling arena team charters in Gadgetzan and outside the arenas in Nagrand and the Blade\'s Edge Mountains.','The goblin Steamwheedle Fighting Circuit has begun. You can find Arena Organizers selling arena team charters in Gadgetzan and outside the arenas in Nagrand and the Blade\'s Edge Mountains.',26124),(19780,'frFR','La Fédération de Rencontres d’Arène de Gentepression a lancé son championnat. Vous trouverez des chartes d’équipe d’arène en vente auprès des organisateurs de combats à Gadgetzan et devant l’entrée des arènes de Nagrand et des Tranchantes.','La Fédération de Rencontres d’Arène de Gentepression a lancé son championnat. Vous trouverez des chartes d’équipe d’arène en vente auprès des organisateurs de combats à Gadgetzan et devant l’entrée des arènes de Nagrand et des Tranchantes.',26124),(19781,'enUS','The goblin Steamwheedle Fighting Circuit is beginning soon. They\'re holding practice matches in their arenas now, but ranking fights begin in $4262d.','The goblin Steamwheedle Fighting Circuit is beginning soon. They\'re holding practice matches in their arenas now, but ranking fights begin in $4262d.',26124),(19781,'frFR','La Fédération de Rencontres d’Arène de Gentepression v